return ['domain'=>'tag-groups','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'el','project-id-version'=>'Tag Groups 2.1.2','pot-creation-date'=>'2026-06-15T12:41:40+00:00','po-revision-date'=>'2026-06-15 13:21+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['Tag Groups'=>'Tag-Groups','https://wordpress.org/plugins/tag-groups/'=>'https://wordpress.org/plugins/tag-groups/','Tag Groups allows you to organize your WordPress taxonomy terms and show them in clouds, tabs, accordions, tables, lists and much more.'=>'Το Tag-Groups σας επιτρέπει να οργανώνετε τους όρους ταξινόμησης του WordPress και να τους εμφανίζετε σε σύννεφα, καρτέλες, ακορντεόν, πίνακες, λίστες και πολλά άλλα.','TaxoPress'=>'TaxoPress','https://taxopress.com'=>'https://taxopress.com','Home'=>'Αρχική','Taxonomies'=>'Taxonomies','Front End'=>'Μπροστινή Εμφάνιση','Back End'=>'Πίσω Εμφάνιση','First Steps'=>'Πρώτα Βήματα','Setup Wizard'=>'Οδηγός Ρύθμισης','Settings'=>'Ρυθμίσεις','Tag Group Admin'=>'Διαχείριση Ομάδας Ετικετών','The term has been removed from all groups.'=>'Ο όρος έχει αφαιρεθεί από όλες τις ομάδες.','Edit this item inline'=>'Επεξεργαστείτε αυτό το στοιχείο inline','Quick&nbsp;Edit'=>'Γρήγορη&nbsp;Επεξεργασία','Please <a %s>click here to run the migration routines</a> to make sure we have migrated all tags.'=>'Παρακαλώ <a %s>κάντε κλικ εδώ για να εκτελέσετε τις διαδικασίες μετανάστευσης</a> για να βεβαιωθείτε ότι έχουμε μεταναστεύσει όλες τις ετικέτες.','Your settings/groups and your terms have been exported. Please download the resulting files with right-click or ctrl-click:'=>'Οι ρυθμίσεις/ομάδες σας και οι όροι σας έχουν εξαχθεί. Παρακαλώ κατεβάστε τα παραγόμενα αρχεία με δεξί κλικ ή ctrl-click:','Writing of the exported settings failed.'=>'Η εγγραφή των εξαχθέντων ρυθμίσεων απέτυχε.','The groups have been sorted alphabetically.'=>'Οι ομάδες έχουν ταξινομηθεί αλφαβητικά.','The label cannot be empty.'=>'Η ετικέτα δεν μπορεί να είναι κενή.','A tag group with the label \'%s\' already exists, or the label has not changed. Please choose another one or go back.'=>'Υπάρχει ήδη μια ομάδα ετικετών με την ετικέτα \'%s\', ή η ετικέτα δεν έχει αλλάξει. Παρακαλώ επιλέξτε μια άλλη ή επιστρέψτε.','A new tag group with the label \'%s\' has been created!'=>'Δημιουργήθηκε μια νέα ομάδα ετικετών με την ετικέτα \'%s\'!','A tag group with the label \'%s\' already exists.'=>'Υπάρχει ήδη μια ομάδα ετικετών με την ετικέτα \'%s\'.','The tag group with the label \'%s\' has been saved!'=>'Η ομάδα ετικετών με την ετικέτα \'%s\' έχει αποθηκευτεί!','A tag group with the id %1$s and the label \'%2$s\' has been deleted.'=>'Μια ομάδα ετικετών με το ID %1$s και την ετικέτα \'%2$s\' έχει διαγραφεί.','Error uploading the file.'=>'Σφάλμα κατά την ανέβασμα του αρχείου.','Error reading the file.'=>'Σφάλμα κατά την ανάγνωση του αρχείου.','Error parsing the file.'=>'Σφάλμα κατά την ανάλυση του αρχείου.','date unknown'=>'η ημερομηνία είναι άγνωστη','Your settings and groups have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'Οι ρυθμίσεις και οι ομάδες σας έχουν εισαχθεί από το αρχείο %1$s (δημιουργήθηκε με την έκδοση πρόσθετου %2$s στις %3$s).','%d option was added or changed.'=>'%d επιλογή προστέθηκε ή άλλαξε.' . "\0" . '%d επιλογές προστέθηκαν ή άλλαξαν.','Your terms have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'Οι όροι σας έχουν εισαχθεί από το αρχείο %1$s (δημιουργήθηκε με την έκδοση πρόσθετου %2$s στις %3$s).','We processed %d term.'=>'Επεξεργαστήκαμε %d όρο.' . "\0" . 'Επεξεργαστήκαμε %d όρους.','We saved %d term.'=>'Αποθηκεύσαμε %d όρο.' . "\0" . 'Αποθηκεύσαμε %d όρους.','The group info of %d term was updated.'=>'Η πληροφορία της ομάδας του %d όρου ενημερώθηκε.' . "\0" . 'Η πληροφορία της ομάδας των %d όρων ενημερώθηκε.','Filters'=>'Φίλτρα','Gutenberg'=>'Gutenberg','Multilingual'=>'Πολυγλωσσική','Shortcodes'=>'Συντομεύσεις','Themes and Appearance'=>'Θέματα και Εμφάνιση','remove'=>'αφαίρεση','(recommended)'=>'(συνιστάται)','keep'=>'διατήρηση','use unfiltered_html filter'=>'χρήση φίλτρου unfiltered_html','First Aid'=>'Πρώτες Βοήθειες','REST API'=>'REST API','System Information'=>'Πληροφορίες Συστήματος','Debugging'=>'Αποσφαλμάτωση','Export/Import'=>'Εξαγωγή/Εισαγωγή','Reset'=>'Επαναφορά','Licences'=>'Άδειες','Transients'=>'Προσωρινά','Database'=>'Βάση Δεδομένων','Filesystem'=>'Σύστημα Αρχείων','WP Object Cache'=>'WP Object Cache','Your settings have been saved.'=>'Οι ρυθμίσεις σας έχουν αποθηκευτεί.','Your settings has been saved.'=>'Οι ρυθμίσεις σας έχουν αποθηκευτεί.','All groups have been deleted and assignments reset.'=>'Όλες οι ομάδες έχουν διαγραφεί και οι αναθέσεις έχουν επαναφερθεί.','The filter on the tags page has been reset to show all tags.'=>'Το φίλτρο στη σελίδα ετικετών έχει επαναφερθεί για να εμφανίζει όλες τις ετικέτες.','tag groups'=>'tag groups','tag cloud'=>'tag cloud','group info'=>'group info','sidebar widget'=>'sidebar widget','accordion'=>'accordion','tabs'=>'tabs','alphabetical'=>'alphabetical','post list'=>'post list','colors'=>'colors','tag description'=>'tag description','tag filter'=>'tag filter','post filter'=>'post filter','backup'=>'backup','remove plugin'=>'remove plugin','remove data'=>'remove data','delete groups'=>'delete groups','debugging'=>'debugging','PHP Version'=>'PHP Version','Ajax Test'=>'Ajax Test','troubleshooting'=>'troubleshooting','benchmarks'=>'δείκτες','speed test'=>'δοκιμή ταχύτητας','error'=>'σφάλμα','testing'=>'δοκιμή','help'=>'βοήθεια','Tag Groups Pro'=>'Tag Groups Pro','upgrade'=>'αναβάθμιση','more groups'=>'περισσότερες ομάδες','posts'=>'αναρτήσεις','filter'=>'φίλτρο','animated'=>'κινούμενα','searchable'=>'αναζητήσιμο','Info'=>'Πληροφορίες','author'=>'συγγραφέας','version'=>'έκδοση','contact'=>'επικοινωνία','about'=>'σχετικά','Licenses'=>'Άδειες','Credits'=>'Πιστώσεις','Development News'=>'Νέα Ανάπτυξης','blog'=>'ιστολόγιο','updates'=>'ενημερώσεις','getting started'=>'ξεκινώντας','introduction'=>'εισαγωγή','sample'=>'δείγμα','migrate'=>'μεταφορά','problem'=>'πρόβλημα','live block preview'=>'προεπισκόπηση ζωντανών μπλοκ','translation'=>'μετάφραση','Migrating the term meta'=>'Μεταφορά του όρου meta','Fixing incorrect tag groups'=>'Διόρθωση λανθασμένων ομάδων ετικετών','Fixing incorrect groups in term meta'=>'Διόρθωση λανθασμένων ομάδων στο meta του όρου','Sorting groups in term meta'=>'Ταξινόμηση ομάδων στο meta του όρου','Checking the tag names'=>'Έλεγχος των ονομάτων ετικετών','Start'=>'Έναρξη','Sample Content'=>'Δείγμα Περιεχομένου','Sample Group A'=>'Δείγμα Ομάδας A','Sample Group B'=>'Δείγμα Ομάδας B','Sample Group C'=>'Δείγμα Ομάδας C','First Sample Tag'=>'Πρώτη Ετικέτα Δείγματος','Second Sample Tag'=>'Δεύτερη Δειγματική Ετικέτα','Third Sample Tag'=>'Τρίτη Δειγματική Ετικέτα','Create a draft sample page with Gutenberg blocks.'=>'Δημιουργήστε μια δειγματική σελίδα προσχέδιο με μπλοκ Gutenberg.','Create a draft sample page with shortcodes.'=>'Δημιουργήστε μια δειγματική σελίδα προσχέδιο με shortcodes.','The plugin %1$s requires WordPress %2$s to function properly.'=>'Το plugin %1$s απαιτεί WordPress %2$s για να λειτουργήσει σωστά.','Please upgrade WordPress and then try again.'=>'Παρακαλώ αναβαθμίστε το WordPress και δοκιμάστε ξανά.','not assigned'=>'μη ανατεθειμένο','You\'re using Tag Groups Free. The Pro version has more features and support. %sUpgrade to Pro%s'=>'Χρησιμοποιείτε την Έκδοση Tag Groups Free. Η Pro έκδοση έχει περισσότερες δυνατότητες και υποστήριξη. %sΑναβάθμιση σε Pro%s','Upgrade to Pro'=>'Αναβάθμιση σε Pro','Upgrade to Tag Groups Pro'=>'Αναβάθμιση σε Tag Groups Pro','Enhance the power of Tag Groups with the Pro version:'=>'Ενισχύστε τη δύναμη των Tag Groups με την Pro έκδοση:','21 Shortcodes'=>'21 Shortcodes','18 Gutenberg Blocks'=>'18 Μπλοκ Gutenberg','Table Tag Cloud'=>'Cloud Ετικετών Πίνακας','Simple Tag Cloud'=>'Απλός Cloud Ετικετών','Shuffle Box'=>'Κουτί Ανακάτεμα','Caching'=>'Caching','Multiple Groups Per Tag'=>'Πολλές Ομάδες Ανά Ετικέτα','Tag Cloud Search'=>'Αναζήτηση Cloud Ετικετών','Toggle Post Filter'=>'Εναλλαγή Φίλτρου Δημοσίευσης','Dynamic Post Filter'=>'Δυναμικό Φίλτρο Δημοσίευσης','Post List'=>'Λίστα Δημοσιεύσεων','Tag Meta Box'=>'Μετα-κουτί Ετικετών','Post Tags in Groups'=>'Ετικέτες Δημοσιεύσεων σε Ομάδες','Permissions'=>'Άδειες','Default Groups'=>'Προεπιλεγμένες Ομάδες','WooCommerce Attributes'=>'Χαρακτηριστικά WooCommerce','Parent Group Level'=>'Επίπεδο Γονικής Ομάδας','Need Tag Groups Support?'=>'Χρειάζεστε υποστήριξη για Ομάδες Ετικετών;','If you need help or have a new feature request, let us know.'=>'Εάν χρειάζεστε βοήθεια ή έχετε αίτημα για νέα δυνατότητα, ενημερώστε μας.','Request Support'=>'Αίτημα Υποστήριξης','Detailed documentation is also available on the plugin website.'=>'Λεπτομερής τεκμηρίωση είναι επίσης διαθέσιμη στην ιστοσελίδα του πρόσθετου.','View Knowledge Base'=>'Δείτε τη Βάση Γνώσεων','The free Tag Groups plugin cannot be active together with Tag Groups Pro.'=>'Το δωρεάν πρόσθετο Ομάδες Ετικετών δεν μπορεί να είναι ενεργό μαζί με το Tag Groups Pro.','more information'=>'περισσότερες πληροφορίες','Edit tag groups'=>'Επεξεργασία ομάδων ετικετών','Clicking will leave this page without saving.'=>'Η κλικ θα σας αφήσει αυτή τη σελίδα χωρίς αποθήκευση.','Welcome to %s!'=>'Καλώς ήρθατε στο %s!','The plugin is ready for use. If you need some assistance, we can walk you through the basic steps.'=>'Το πρόσθετο είναι έτοιμο προς χρήση. Εάν χρειάζεστε βοήθεια, μπορούμε να σας καθοδηγήσουμε στα βασικά βήματα.','Start the Setup Wizard'=>'Ξεκινήστε τον Οδηγό Ρύθμισης','Or click here if you prefer to do it on your own.'=>'Ή κάντε κλικ εδώ αν προτιμάτε να το κάνετε μόνοι σας.','Go to the <span class="dashicons dashicons-tag"></span>&nbsp;Tag Groups <a %s>taxonomy settings</a> and <b>select the taxonomy</b> (tag type) of your tags. In most cases just leave the default: Tags (post_tag).'=>'Μεταβείτε στις <span class="dashicons dashicons-tag"></span>&nbsp;Ρυθμίσεις Ομάδων Ετικετών <a %s>taxonomy</a> και <b>επιλέξτε την taxonomy</b> (τύπος ετικέτας) των ετικετών σας. Στις περισσότερες περιπτώσεις αφήστε την προεπιλογή: Ετικέτες (post_tag).','Go to the tag groups admin page and <b>create some groups</b>.'=>'Μεταβείτε στη σελίδα διαχείρισης ομάδων ετικετών και <b>δημιουργήστε κάποιες ομάδες</b>.','You can find these pages listed on your <a %s>Tag Groups home page</a>.'=>'Μπορείτε να βρείτε αυτές τις σελίδες καταχωρημένες στη <a %s>σελίδα αρχικής Ομάδων Ετικετών</a> σας.','Go to your tags and <b>assign them to these groups</b>.'=>'Μεταβείτε στις ετικέτες σας και <b>αναθέστε τις σε αυτές τις ομάδες</b>.','Filter by tag group'=>'Φιλτράρετε ανά ομάδα ετικετών','%s created this sample page in the Setup Wizard of the <b>Tag Groups</b> plugin. You can safely edit and delete it or keep it for future reference.'=>'%s δημιούργησε αυτή τη δείγμα σελίδα στον Οδηγό Ρυθμίσεων του <b>Plugin Ομάδων Ετικετών</b>. Μπορείτε να την επεξεργαστείτε με ασφάλεια ή να την διαγράψετε ή να την κρατήσετε για μελλοντική αναφορά.','The following shortcodes use a variety of parameters so that you can get an idea of the options. Feel free to generate a new sample page with more features after upgrading the plugin.'=>'Οι παρακάτω σύντομοι κωδικοί χρησιμοποιούν μια ποικιλία παραμέτρων ώστε να έχετε μια ιδέα των επιλογών. Μη διστάσετε να δημιουργήσετε μια νέα δείγμα σελίδα με περισσότερες δυνατότητες μετά την αναβάθμιση του plugin.','Please find links to the documentation in the <a %s>Tag Groups settings</a>.'=>'Παρακαλώ βρείτε συνδέσμους προς την τεκμηρίωση στις <a %s>ρυθμίσεις Ομάδων Ετικετών</a>.','Tabbed Tag Cloud'=>'Κατηγοριοποιημένο Νέφος Ετικετών','Accordion Tag Cloud'=>'Συρόμενο Νέφος Ετικετών','Alphabetical Tag Cloud'=>'Αλφαβητικό Νέφος Ετικετών','Tag List'=>'Λίστα Ετικετών','Alphabetical Tag Index'=>'Αλφαβητικός Ευρετήρας Ετικετών','The following blocks use a variety of parameters so that you can get an idea of the options. Feel free to generate a new sample page with more features after upgrading the plugin.'=>'Οι παρακάτω μπλοκ χρησιμοποιούν μια ποικιλία παραμέτρων ώστε να έχετε μια ιδέα των επιλογών. Μη διστάσετε να δημιουργήσετε μια νέα δείγμα σελίδα με περισσότερες δυνατότητες μετά την αναβάθμιση του plugin.','This page was created while you had the Gutenberg editor enabled. Therefore the features only display while Gutenberg is active.'=>'Αυτή η σελίδα δημιουργήθηκε ενώ είχατε ενεργοποιημένο τον επεξεργαστή Gutenberg. Επομένως, οι δυνατότητες εμφανίζονται μόνο ενώ ο Gutenberg είναι ενεργός.','Display filter on the "Posts" screen.'=>'Εμφάνιση φίλτρου στην οθόνη "Δημοσιεύσεις".','Add a pull-down menu to the filters above the list of posts. If you filter posts by tag groups, then only items will be shown that have tags (terms) in that particular group. This feature can be turned off so that the menu won\'t obstruct your screen if you use a high number of groups. May not work with all taxonomies.'=>'Προσθέστε ένα αναδυόμενο μενού στα φίλτρα πάνω από τη λίστα δημοσιεύσεων. Αν φιλτράρετε τις δημοσιεύσεις κατά ομάδες ετικετών, τότε θα εμφανίζονται μόνο τα στοιχεία που έχουν ετικέτες (όρους) σε αυτήν την συγκεκριμένη ομάδα. Αυτή η δυνατότητα μπορεί να απενεργοποιηθεί, ώστε το μενού να μην εμποδίζει την οθόνη σας αν χρησιμοποιείτε μεγάλο αριθμό ομάδων. Μπορεί να μην λειτουργεί με όλες τις taxonomies.','Display filter on the "Tags" screen.'=>'Εμφάνιση φίλτρου στην οθόνη "Ετικέτες".','Add a filter to the list of tags. Disable it here if it conflicts with other plugins or themes.'=>'Προσθέστε ένα φίλτρο στη λίστα ετικετών. Απενεργοποιήστε το εδώ αν συγκρούεται με άλλα plugins ή θέματα.','Save Settings'=>'Αποθήκευση Ρυθμίσεων','Gutenberg block preview'=>'προεπισκόπηση μπλοκ Gutenberg','Some blocks can show an approximate preview in the Gutenberg editor. If you deactivate this option, then all blocks will show a static icon with text.'=>'Ορισμένα μπλοκ μπορούν να δείξουν μια περίπου προεπισκόπηση στον επεξεργαστή Gutenberg. Αν απενεργοποιήσετε αυτή την επιλογή, τότε όλα τα μπλοκ θα δείχνουν μια στατική εικονίδιο με κείμενο.','Keep groups of translations in sync'=>'Διατηρήστε τις ομάδες μεταφράσεων συγχρονισμένες','If you activate this option, we try to sync the groups across all language versions of a tag when you save it. Deactivate it to set groups independently.'=>'Αν ενεργοποιήσετε αυτή την επιλογή, προσπαθούμε να συγχρονίσουμε τις ομάδες σε όλες τις γλωσσικές εκδόσεις μιας ετικέτας όταν την αποθηκεύετε. Απενεργοποιήστε το για να ρυθμίσετε τις ομάδες ανεξάρτητα.','All Tag Groups features are available as Gutenberg blocks. You can also use shortcodes.'=>'Όλες οι δυνατότητες των Ομάδων Ετικετών είναι διαθέσιμες ως μπλοκ Gutenberg. Μπορείτε επίσης να χρησιμοποιήσετε shortcodes.','Click on the features for more information.'=>'Κάντε κλικ στις δυνατότητες για περισσότερες πληροφορίες.','Display the tags in a tabbed tag cloud.'=>'Εμφάνιση των ετικετών σε μια καρτέλα ετικετών.','Example'=>'Παράδειγμα','Parameters'=>'Παράμετροι','Please find the parameters in the <a %s>documentation</a>.'=>'Παρακαλώ βρείτε τις παραμέτρους στην <a %s>τεκμηρίωση</a>.','Accordion'=>'Ακορντεόν','Display the tags in an accordion.'=>'Εμφάνιση των ετικετών σε ένα ακορντεόν.','Display the tags in lists under tag groups.'=>'Εμφάνιση των ετικετών σε λίστες κάτω από ομάδες ετικετών.','Display the tags in tabbed tag cloud with first letters as tabs.'=>'Εμφάνιση των ετικετών σε καρτέλες με τις πρώτες γράμματα ως καρτέλες.','(Not tested with right-to-left languages.)'=>'(Δεν έχει δοκιμαστεί με γλώσσες από δεξιά προς αριστερά.)','Display the tags in a list with first letters as heading.'=>'Εμφάνιση των ετικετών σε μια λίστα με τις πρώτες γράμματα ως κεφαλίδα.','Group Information'=>'Πληροφορίες Ομάδας','Display information about tag groups.'=>'Εμφάνιση πληροφοριών σχετικά με τις ομάδες ετικετών.','The function <b>tag_groups_cloud</b> accepts the same parameters as the [tag_groups_cloud] shortcode, except for those that determine tabs and styling.'=>'Η λειτουργία <b>tag_groups_cloud</b> δέχεται τις ίδιες παραμέτρους με το shortcode [tag_groups_cloud], εκτός από αυτές που καθορίζουν τις καρτέλες και το στυλ.','By default it returns a string with the html for a tabbed tag cloud.'=>'Από προεπιλογή επιστρέφει μια συμβολοσειρά με το html για μια καρτέλα tag cloud.','If the optional second parameter is set to \'true\', the function returns a multidimensional array containing tag groups and tags.'=>'Εάν ο προαιρετικός δεύτερος παράμετρος είναι ρυθμισμένος σε \'true\', η συνάρτηση επιστρέφει ένα πολυδιάστατο πίνακα που περιέχει ομάδες tags και tags.','Enable shortcode in sidebar widgets (if not visible anyway).'=>'Ενεργοποιήστε το shortcode στα sidebar widgets (εάν δεν είναι ορατά ούτως ή άλλως).','Always load shortcode scripts.'=>'Φορτώστε πάντα τα scripts του shortcode.','Click for more information'=>'Κάντε κλικ για περισσότερες πληροφορίες','Turn off to load the scripts only on posts and pages where a shortcode appears.'=>'Απενεργοποιήστε το για να φορτώνονται τα scripts μόνο σε αναρτήσεις και σελίδες όπου εμφανίζεται ένα shortcode.','Turn on if you use these shortcodes in widgets.'=>'Ενεργοποιήστε το εάν χρησιμοποιείτε αυτά τα shortcodes σε widgets.','Here you can choose a theme for the Tabbed Tag Cloud and the Accordion Tag Cloud.'=>'Εδώ μπορείτε να επιλέξετε ένα θέμα για το Tabbed Tag Cloud και το Accordion Tag Cloud.','New themes can be created with the <a href="http://jqueryui.com/themeroller/" target="_blank">jQuery UI ThemeRoller</a>:'=>'Νέα θέματα μπορούν να δημιουργηθούν με το <a href="http://jqueryui.com/themeroller/" target="_blank">jQuery UI ThemeRoller</a>:','On the page "Theme Roller" you can customize all features or pick one set from the gallery. Finish with the "download" button.'=>'Στη σελίδα "Theme Roller" μπορείτε να προσαρμόσετε όλες τις δυνατότητες ή να επιλέξετε ένα σετ από την γκαλερί. Ολοκληρώστε με το κουμπί "download".','On the next page ("Download Builder") you will need to select the version 1.12.x and the components "Widget", "Accordion" and "Tabs". Make sure that before downloading you enter at the bottom as "CSS Scope" <b>.tag-groups-cloud</b> (including the dot).'=>'Στην επόμενη σελίδα ("Download Builder") θα χρειαστεί να επιλέξετε την έκδοση 1.12.x και τα στοιχεία "Widget", "Accordion" και "Tabs". Βεβαιωθείτε ότι πριν από τη λήψη εισάγετε κάτω ως "CSS Scope" <b>.Tag-Groups</b> (συμπεριλαμβανομένης της τελείας).','Then you unpack the downloaded zip file. You will need the "images" folder and the "jquery-ui.theme.min.css" file.'=>'Στη συνέχεια, αποσυμπιέστε το κατεβασμένο zip αρχείο. Θα χρειαστείτε τον φάκελο "images" και το αρχείο "jquery-ui.theme.min.css".','Create a new folder inside your <i>wp-content/uploads</i> folder (for example "my-theme") and copy there these two items.'=>'Δημιουργήστε έναν νέο φάκελο μέσα στον φάκελο σας <i>wp-content/uploads</i> (για παράδειγμα "my-theme") και αντιγράψτε εκεί αυτά τα δύο στοιχεία.','Enter the name of this new folder (for example "my-theme") below.'=>'Εισάγετε το όνομα αυτού του νέου φακέλου (για παράδειγμα "my-theme") παρακάτω.','own theme'=>'Ιδιο θέμα','Don\'t load a theme.'=>'Μην φορτώνετε ένα θέμα.','Here you can turn off jQuery UI themes if your WordPress theme brings its own jQuery UI theme, in order to avoid conflicts.'=>'Εδώ μπορείτε να απενεργοποιήσετε τα θέματα jQuery UI εάν το θέμα WordPress σας φέρνει το δικό του θέμα jQuery UI, προκειμένου να αποφευχθούν συγκρούσεις.','Further options'=>'Περισσότερες επιλογές','Use jQuery.  (Default is on. Other plugins might override this setting.)'=>'Χρησιμοποιήστε jQuery. (Η προεπιλογή είναι ενεργοποιημένη. Άλλα πρόσθετα μπορεί να αντικαταστήσουν αυτήν τη ρύθμιση.)','Tabs triggered by hovering mouse pointer (without clicking).'=>'Καρτέλες που ενεργοποιούνται με την αιώρηση του δείκτη του ποντικιού (χωρίς κλικ).','Collapsible tabs (toggle open/close).'=>'Συμπιεστές καρτέλες (εναλλαγή άνοιγμα/κλείσιμο).','HTML in tag description:'=>'HTML στην περιγραφή του tag:','By default the description appears in a tooltip when you hover the mouse over a tag in a tag cloud.'=>'Από προεπιλογή, η περιγραφή εμφανίζεται σε ένα tooltip όταν τοποθετείτε το ποντίκι πάνω από ένα tag σε μια tag cloud.','If you don\'t trust all users of your site, remove the HTML or use a plugin to give the unfiltered_html capability only to users you trust.'=>'Εάν δεν εμπιστεύεστε όλους τους χρήστες της ιστοσελίδας σας, αφαιρέστε το HTML ή χρησιμοποιήστε ένα plugin για να δώσετε την ικανότητα unfiltered_html μόνο στους χρήστες που εμπιστεύεστε.','Save Theme Options'=>'Αποθήκευση Επιλογών Θέματος','Search for settings'=>'Αναζήτηση ρυθμίσεων','Search for setting pages. Type a space to show all settings.'=>'Αναζητήστε σελίδες ρυθμίσεων. Πληκτρολογήστε ένα κενό για να εμφανίσετε όλες τις ρυθμίσεις.','Search Results'=>'Αποτελέσματα Αναζήτησης','Nothing found'=>'Δεν βρέθηκαν αποτελέσματα','Active Taxonomies'=>'Ενεργές Taxonomies','Group Statistics'=>'Στατιστικά Ομάδας','for the selected language'=>'για την επιλεγμένη γλώσσα','go to tag group administration'=>'πήγαινε στη διαχείριση ομάδας tag','Enable Tag Groups Public API Access'=>'Ενεργοποίηση Δημόσιας Πρόσβασης στο API Ομάδων Tag','Enable public access to tag groups endpoint /wp-json/tag-groups/v1/groups/.'=>'Ενεργοποίηση δημόσιας πρόσβασης στο endpoint των ομάδων tag /wp-json/tag-groups/v1/groups/.','Enable Terms Public API Access'=>'Ενεργοποίηση Δημόσιας Πρόσβασης στο API Όρων','Enable public access to terms endpoint /wp-json/tag-groups/v1/terms/.'=>'Ενεργοποίηση δημόσιας πρόσβασης στο endpoint των όρων /wp-json/tag-groups/v1/terms/.','Choose the taxonomies for which you want to use Tag Groups:'=>'Επιλέξτε τις taxonomies για τις οποίες θέλετε να χρησιμοποιήσετε τις Ομάδες Tag:','The default texonomy is <b>Tags (post_tag)</b>. Please note that the tag clouds might not work with all taxonomies and that some taxonomies listed here may not be accessible in the admin backend. If you don\'t understand what is going on here, just leave the default.'=>'Η προεπιλεγμένη taxonomie είναι <b>Tags (post_tag)</b>. Σημειώστε ότι οι tag clouds μπορεί να μην λειτουργούν με όλες τις taxonomies και ότι ορισμένες taxonomies που αναφέρονται εδώ μπορεί να μην είναι προσβάσιμες στο admin backend. Εάν δεν καταλαβαίνετε τι συμβαίνει εδώ, απλά αφήστε την προεπιλογή.','<b>Please deselect taxonomies that you don\'t use. Using several taxonomies for the same post type or hierarchical taxonomies (like categories) is experimental and not supported.</b>'=>'<b>Παρακαλώ αποεπιλέξτε taxonomies που δεν χρησιμοποιείτε. Η χρήση πολλών taxonomies για τον ίδιο τύπο ανάρτησης ή ιεραρχικών taxonomies (όπως οι κατηγορίες) είναι πειραματική και δεν υποστηρίζεται.</b>','To see the post type, hover your mouse over the option.'=>'Για να δείτε τον τύπο δημοσίευσης, τοποθετήστε το ποντίκι σας πάνω από την επιλογή.','If you use a custom taxonomy, make sure that the attribute "Public" is set to "true" and "Hierarchical" to "false".'=>'Εάν χρησιμοποιείτε μια προσαρμοσμένη taxonomy, βεβαιωθείτε ότι το χαρακτηριστικό "Public" είναι ρυθμισμένο σε "true" και το "Hierarchical" σε "false".','Show hierarchical taxonomies. Not all Tag Groups features will work with these taxonomies.'=>'Εμφάνιση ιεραρχικών taxonomies. Όλες οι δυνατότητες των Ομάδων Ετικετών δεν θα λειτουργούν με αυτές τις taxonomies.','Save Taxonomies'=>'Αποθήκευση Taxonomies','Export'=>'Εξαγωγή','Use this button to export all Tag Groups settings and groups and all terms that are assigned to a group into files.'=>'Χρησιμοποιήστε αυτό το κουμπί για να εξάγετε όλες τις ρυθμίσεις και τις ομάδες των Ετικετών και όλους τους όρους που έχουν ανατεθεί σε μια ομάδα σε αρχεία.','You can import both files separately. Category hierarchy won\'t be saved. When you restore terms that were deleted, they receive new IDs and you must assign them to posts again. Exporting cannot substitute a backup.'=>'Μπορείτε να εισάγετε και τα δύο αρχεία ξεχωριστά. Η ιεραρχία κατηγορίας δεν θα αποθηκευτεί. Όταν αποκαθιστάτε όρους που έχουν διαγραφεί, λαμβάνουν νέες ταυτότητες και πρέπει να τους αναθέσετε ξανά σε δημοσιεύσεις. Η εξαγωγή δεν μπορεί να αντικαταστήσει ένα αντίγραφο ασφαλείας.','Export Files'=>'Αρχεία Εξαγωγής','Import'=>'Εισαγωγή','Below you can import previously exported settings/groups or terms from a file.'=>'Παρακάτω μπορείτε να εισάγετε προηγουμένως εξαγόμενες ρυθμίσεις/ομάδες ή όρους από ένα αρχείο.','It is recommended to back up the database of your site before proceeding.'=>'Συνιστάται να δημιουργήσετε αντίγραφο ασφαλείας της βάσης δεδομένων της ιστοσελίδας σας πριν προχωρήσετε.','Please import the settings before the terms.'=>'Παρακαλώ εισάγετε τις ρυθμίσεις πριν από τους όρους.','Import File'=>'Αρχείο Εισαγωγής','Use this button to delete all tag groups and assignments. Your tags will not be changed. Check the checkbox to confirm.'=>'Χρησιμοποιήστε αυτό το κουμπί για να διαγράψετε όλες τις ομάδες ετικετών και τις αναθέσεις. Οι ετικέτες σας δεν θα αλλάξουν. Ελέγξτε το κουτάκι για να επιβεβαιώσετε.','Please keep in mind that the tag assignments cannot be recovered by the export/import function.'=>'Παρακαλώ έχετε υπόψη σας ότι οι αναθέσεις ετικετών δεν μπορούν να ανακτηθούν από τη λειτουργία εξαγωγής/εισαγωγής.','I know what I am doing.'=>'Ξέρω τι κάνω.','Delete Groups'=>'Διαγραφή Ομάδων','Delete Settings and Groups'=>'Διαγραφή Ρυθμίσεων και Ομάδων','Delete all groups and settings when uninstalling the plugin.'=>'Διαγραφή όλων των ομάδων και ρυθμίσεων κατά την απεγκατάσταση του πρόσθετου.','Debug mode is on.'=>'Η λειτουργία αποσφαλμάτωσης είναι ενεργοποιημένη.','Verbose logging is enabled with CM_DEBUG.'=>'Η αναλυτική καταγραφή είναι ενεργοποιημένη με το CM_DEBUG.','Verbose logging is on.'=>'Η αναλυτική καταγραφή είναι ενεργή.','Turn off '=>'Απενεργοποίηση ','Verbose logging is off.'=>'Η αναλυτική καταγραφή είναι απενεργοποιημένη.','Turn on'=>'Ενεργοποίηση','Debug mode is off.'=>'Η λειτουργία αποσφαλμάτωσης είναι απενεργοποιημένη.','Learn more <a %s>about debugging</a>.'=>'Μάθετε περισσότερα <a %s>για την αποσφαλμάτωση</a>.','Migrate tags to the new format of Tag Groups.'=>'Μεταφορά ετικετών στη νέα μορφή Ομάδων Ετικετών.','The plugin automatically migrates tags to the new format and tries to keep track of changes. There may, however, be cases where other components made unnoticed changes. You might also need to manually migrate tags after you enabled a taxonomy that already contained untracked tags.'=>'Το πρόσθετο μεταφέρει αυτόματα τις ετικέτες στη νέα μορφή και προσπαθεί να παρακολουθεί τις αλλαγές. Ωστόσο, μπορεί να υπάρχουν περιπτώσεις όπου άλλα στοιχεία έκαναν αλλαγές χωρίς να γίνουν αντιληπτές. Ίσως χρειαστεί επίσης να μεταφέρετε χειροκίνητα τις ετικέτες μετά την ενεργοποίηση μιας ταξινόμησης που περιείχε ήδη μη παρακολουθούμενες ετικέτες.','Migrate'=>'Μεταφορά','Running the maintenance can solve issues that you encounter during filtering by tag groups.'=>'Η εκτέλεση της συντήρησης μπορεί να λύσει προβλήματα που ενδέχεται να συναντήσετε κατά την φιλτράρισμα με βάση τις ομάδες ετικετών.','Maintenance'=>'Συντήρηση','Reset the filter on the tags page to show all tags.'=>'Επαναφέρετε το φίλτρο στη σελίδα ετικετών για να εμφανίσετε όλες τις ετικέτες.','Use it if a JavaScript error disables the filter menu. Note that it is still recommended to find out the cause of the error.'=>'Χρησιμοποιήστε το αν ένα σφάλμα JavaScript απενεργοποιήσει το μενού φίλτρου. Σημειώστε ότι εξακολουθεί να συνιστάται να διαπιστώσετε την αιτία του σφάλματος.','Reset Tag Filter'=>'Επαναφορά Φίλτρου Ετικετών','Please stay on this page until all processes have finished.'=>'Παρακαλώ μείνετε σε αυτή τη σελίδα μέχρι να ολοκληρωθούν όλες οι διαδικασίες.','There have been errors.'=>'Υπήρξαν σφάλματα.','Continue'=>'Συνέχεια','Finished!'=>'Ολοκληρώθηκε!','The following terms cannot be used:'=>'Οι παρακάτω όροι δεν μπορούν να χρησιμοποιηθούν:','Number of processed items: '=>'Αριθμός επεξεργασμένων στοιχείων: ','Number of changed items: '=>'Αριθμός αλλαγμένων στοιχείων: ','WordPress Version'=>'WordPress Έκδοση','Site URL'=>'URL Ιστοσελίδας','Home URL'=>'URL Αρχικής Σελίδας','Active Theme'=>'Ενεργό Θέμα','Version'=>'Έκδοση','Checking...'=>'Έλεγχος...','Show the Response'=>'Εμφάνιση της Απόκρισης','passed'=>'επιτυχής','failed'=>'αποτυχία','Benchmarks'=>'Δοκιμές','Cache'=>'Κρυφή μνήμη','Tag groups pro only'=>'Ομάδες ετικετών μόνο για pro','Server'=>'Διακομιστής','Constants'=>'Σταθερές','Well done!'=>'Μπράβο!','Now go the Tag Group Administration.'=>'Τώρα πηγαίνετε στη Διαχείριση Ομάδων Ετικετών.','Or preview the sample page here.'=>'Ή προεπισκοπήστε τη σελίδα δείγμα εδώ.','Or go to the <a %s>Tag Groups settings</a> or visit the <a %s>documentation</a>.'=>'Ή πηγαίνετε στις <a %s>ρυθμίσεις Ομάδων Ετικετών</a> ή επισκεφθείτε την <a %s>τεκμηρίωση</a>.','Now go to the <a %s>Tag Groups settings</a>, or visit the <a %s>documentation</a>.'=>'Τώρα πηγαίνετε στις <a %s>ρυθμίσεις Ομάδων Ετικετών</a>, ή επισκεφτείτε την <a %s>τεκμηρίωση</a>.','If you need to launch the Setup Wizard again, you can find it in the settings. Just enter "wizard" in the search field.'=>'Αν χρειάζεστε να εκκινήσετε ξανά τον Οδηγό Ρύθμισης, μπορείτε να τον βρείτε στις ρυθμίσεις. Απλά εισάγετε "wizard" στο πεδίο αναζήτησης.','Happy tagging!'=>'Καλή ετικετοποίηση!','Tag Groups Setup Wizard'=>'Οδηγός Ρύθμισης Ομάδων Ετικετών','Now you are ready to create your own tag groups. If you prefer to start out from a sample, we will create for you three groups and three tags. You can play around with them, rename or delete them.'=>'Τώρα είστε έτοιμοι να δημιουργήσετε τις δικές σας ομάδες ετικετών. Αν προτιμάτε να ξεκινήσετε από ένα δείγμα, θα δημιουργήσουμε για εσάς τρεις ομάδες και τρεις ετικέτες. Μπορείτε να πειραματιστείτε μαζί τους, να τα μετονομάσετε ή να τα διαγράψετε.','Create sample groups:'=>'Δημιουργία δειγματικών ομάδων:','Create sample tags in these groups:'=>'Δημιουργία δειγματικών ετικετών σε αυτές τις ομάδες:','Next Step'=>'Επόμενο Βήμα','On the following pages we will guide you through the basic settings that you need for the most common features.'=>'Στις επόμενες σελίδες θα σας καθοδηγήσουμε μέσα από τις βασικές ρυθμίσεις που χρειάζεστε για τις πιο κοινές δυνατότητες.','You can later make changes or fine-tune the details in the Tag Groups settings.'=>'Αργότερα μπορείτε να κάνετε αλλαγές ή να ρυθμίσετε τις λεπτομέρειες στις ρυθμίσεις Ομάδων Ετικετών.','(show me the menu)'=>'(δείξε μου το μενού)','Feel free to abort the Setup Wizard any time and continue on your own path. You can also launch it again at a later time.'=>'Μη διστάσετε να ακυρώσετε τον Οδηγό Ρύθμισης οποιαδήποτε στιγμή και να συνεχίσετε μόνοι σας. Μπορείτε επίσης να τον εκκινήσετε ξανά αργότερα.','The wizard will offer more options after upgrading to premium.'=>'Ο οδηγός θα προσφέρει περισσότερες επιλογές μετά την αναβάθμιση σε premium.','Choose the taxonomies for which you want to use tag groups.'=>'Επιλέξτε τις taxonomies για τις οποίες θέλετε να χρησιμοποιήσετε ομάδες ετικετών.','In most cases the default taxonomy <b>Tags (post_tag)</b> will do the job.'=>'Στις περισσότερες περιπτώσεις η προεπιλεγμένη taxonomy <b>Tags (post_tag)</b> θα κάνει τη δουλειά.','post type'=>'post type','You will find more options in the Tag Groups settings.'=>'Θα βρείτε περισσότερες επιλογές στις ρυθμίσεις Ομάδων Ετικετών.','Tag Group Administration'=>'Διαχείριση Ομάδας Ετικετών','Filter by label'=>'Φιλτράρισμα ανά ετικέτα','Tag Group name'=>'Όνομα Ομάδας Ετικετών','Number of assigned tags'=>'Αριθμός ανατεθέντων ετικετών','Actions'=>'Ενέργειες','Change order'=>'Αλλαγή σειράς','Group ID'=>'ID ομάδας','Edit'=>'Επεξεργασία','Create'=>'Δημιουργία','new'=>'νέα','label'=>'ετικέτα','Delete this group.'=>'Διαγράψτε αυτή την ομάδα.','Create a new group below.'=>'Δημιουργήστε μια νέα ομάδα παρακάτω.','Add New Tag Group'=>'Προσθήκη Νέας Ομάδας Ετικετών','move up'=>'μετακίνηση προς τα πάνω','move down'=>'μετακίνηση προς τα κάτω','reload'=>'αναφόρτωση','next page'=>'επόμενη σελίδα','previous page'=>'προηγούμενη σελίδα','go to page:'=>'μετάβαση στη σελίδα:','Show posts'=>'Εμφάνιση δημοσιεύσεων','Show tags'=>'Εμφάνιση ετικετών','Do you really want to delete this tag group?'=>'Θέλετε πραγματικά να διαγράψετε αυτή την ομάδα ετικετών;','Please visit <a %s>%s</a>.'=>'Παρακαλώ επισκεφθείτε <a %s>%s</a>.','Read more'=>'Διαβάστε περισσότερα','Thanks for using Tag Groups | %1sTaxoPress.com%2s | Version %3s'=>'Ευχαριστώ που χρησιμοποιείτε τις Ομάδες Ετικετών | %1sTaxoPress.com%2s | Έκδοση %3s','Assign to'=>'Ανάθεση σε','Filter off'=>'Φίλτρο εκτός','Please select one of the languages above to see the correct tag groups!'=>'Παρακαλώ επιλέξτε μία από τις γλώσσες παραπάνω για να δείτε τις σωστές ομάδες ετικετών!','Groups'=>'Ομάδες','You\'re using Tag Groups Free. The Pro version has more features and support. %1$sUpgrade to Pro%2$s'=>'Χρησιμοποιείτε τις Ομάδες Ετικετών Δωρεάν. Η Pro έκδοση έχει περισσότερες δυνατότητες και υποστήριξη. %1$sΑναβάθμιση σε Pro%2$s','Or go to the <a %1$s>Tag Groups settings</a> or visit the <a %2$s>documentation</a>.'=>'Ή μεταβείτε στις <a %1$s>ρυθμίσεις των Ομάδων Ετικετών</a> ή επισκεφθείτε την <a %2$s>τεκμηρίωση</a>.','Now go to the <a %1$s>Tag Groups settings</a>, or visit the <a %2$s>documentation</a>.'=>'Τώρα μεταβείτε στις <a %1$s>ρυθμίσεις των Ομάδων Ετικετών</a>, ή επισκεφθείτε την <a %2$s>τεκμηρίωση</a>.','Please visit <a %1$s>%2$s</a>.'=>'Παρακαλώ επισκεφθείτε <a %1$s>%2$s</a>.','Thanks for using Tag Groups | %1$sTaxoPress.com%2$s | Version %3$s'=>'Ευχαριστώ που χρησιμοποιείτε τις Ομάδες Ετικετών | %1$sTaxoPress.com%2$s | Έκδοση %3$s']];